// GetItemParams defines parameters for GetItem.
type GetItemParams struct {
	// Fieldgroups This parameter controls what is returned in the response. If this field is not set, the method returns all the details of the item.<br><br><span class="tablenote"><b>Note:</b> Multiple <b>fieldgroups</b> can be set and applied simultaneously. However, <b>COMPACT</b> <b>must</b> be used alone. Otherwise, an error will occur.</span><br><b>Valid Values:</b><ul><li><b>PRODUCT</b><br>This field group adds the <a href="/api-docs/buy/browse/resources/item/methods/getItem#response.product">product</a> container to the response.</li><li><b>COMPACT</b></br>This field group returns only the following fields which let you quickly check if the availability or price of the item has changed, if the item has been revised by the seller, or if an item's top-rated plus status has changed for items you have stored.<ul><li><b>itemId</b></li><li><b>bidCount</b></li><li><b>currentBidPrice</b></li><li><b>eligibleForInlineCheckout</b></li><li><b>estimatedAvailabilities</b></li><li><b>gtin</b></li><li><b>immediatePay</b></li><li><b>itemAffiliateWebURL</b></li><li><b>itemCreationDate</b></li><li><b>itemWebUrl</b></li><li><b>legacyItemId</b></li><li><b>minimumPriceToBid</b></li><li><b>price</b></li><li><b>priorityListing</b></li><li><b>reservePriceMet</b></li><li><b>sellerItemRevision</b></li><li><b>shippingOptions</b></li><li><b>taxes</b></li><li><b>topRatedBuyingExperience</b></li><li><b>uniqueBidderCount</b></li></ul>For Example:<br>To determine if a stored item's information is current, perform the following:<ol><li>Pass in the item ID and set <code>fieldgroups</code> to <code>COMPACT</code>.<pre>item/v1|4**********8|0?fieldgroups=COMPACT</pre></li><li>Do one of the following:<ul><li>If <b>sellerItemRevision</b> is returned and a revision number for this item <i>has not</i> been stored, record the number and pass in the item ID in the <b>getItem</b> method to retrieve the most recent information.</li><li>If the revision number is different from the value you have stored, update the value and pass in the item ID in the <b>getItem</b> method to retrieve the most recent information.</li><li>If <code>sellerItemRevision</code> is <i>not</i> returned or has not changed, where needed, update the item information with the information returned in the response.</li></ul></li></ol></li><li><b>ADDITIONAL_SELLER_DETAILS</b><br>This adds the <a href="/api-docs/buy/browse/resources/item/methods/getItem#response.seller.userId">userId</a> field to the response.</li></ul>
	Fieldgroups *string `form:"fieldgroups,omitempty" json:"fieldgroups,omitempty"`

	// QuantityForShippingEstimate This query parameter sets the item quantity to be used when calculating the shipping estimate information returned in the <a href="/api-docs/buy/browse/resources/item/methods/getItem#response.shippingOptions">shippingOptions</a> container of the response.<br><br>This value must be a positive integer value and should not exceed the quantity available in the listing. This field is not recommended for auction listings, as they will always have a quantity of 1.
	QuantityForShippingEstimate *string `form:"quantity_for_shipping_estimate,omitempty" json:"quantity_for_shipping_estimate,omitempty"`

	// XEBAYCENDUSERCTX This header is can be used in following two situations:<br><ul><li>To retrieve the <b>itemAffiliateWebUrl</b> field in the response, the ePN affiliate can pass in their affiliate credentials using this header. For more information, see <a href="/api-docs/buy/static/api-browse.html#affiliate-header" target="_blank ">Header for affiliate information.</a></li><li>If the listing is using calculated or flat-rate shipping with shipping rate tables, the user can use this header to provide country and postal code in order for the <b>shippingOption</b> container, which includes shipping costs and delivery estimates, to be returned. For more information, see <a href="/api-docs/buy/static/api-browse.html#X-EBAY-C-ENDUSERCTX-context" target="_blank ">Header for shipping information accuracy.</a></li></ul>
	XEBAYCENDUSERCTX *string `json:"X-EBAY-C-ENDUSERCTX,omitempty"`

	// XEBAYCMARKETPLACEID This header identifies the seller's eBay marketplace. It is required for all marketplaces outside of the US.<br><br><span class="tablenote"><b>Note:</b> If the marketplace ID value is invalid or missing, the default value of <code>EBAY_US</code> is used.</span><br>See <a href="/api-docs/buy/browse/types/ba:MarketplaceIdEnum" target="_blank">MarketplaceIdEnum</a> for a list of supported marketplaces.<br><br><b>Default:</b> <code>EBAY_US</code>
	XEBAYCMARKETPLACEID *string `json:"X-EBAY-C-MARKETPLACE-ID,omitempty"`

	// AcceptLanguage This header is used to indicate the natural language and locale preferred by the user for the response.<br><br>This header is required when targeting a specific locale of a marketplace that supports multiple locales. For example:<ul><li>When targeting the French locale of the Belgium marketplace, it is required to pass in <code>fr-BE</code> to specify this. If this locale is not specified, the language will default to Dutch.</li><li>When targeting the French locale of the Canadian marketplace, it is required to pass in <code>fr-CA</code> to specify this. If this locale is not specified, the language will default to English.</li></ul>
	AcceptLanguage *string `json:"Accept-Language,omitempty"`
}

